<template>
  <section class="about-page w-full bg-[#F9F5F0] dark:bg-[#0f172a] pb-10 pt-3 md:pb-16 md:pt-5">
    <div class="mx-auto flex w-full max-w-[1120px] flex-col gap-8 md:gap-10">
      <section
        class="rounded-[34px] bg-[#EFF3EF] px-4 py-6 shadow-[0_20px_48px_rgba(43,73,73,0.08)] dark:bg-[#172a31] dark:shadow-[0_24px_54px_rgba(0,0,0,0.28)] md:px-10 md:py-9"
      >
        <div class="max-w-[780px]">
          <h1
            class="font-display text-[2.25rem] font-medium leading-[1.02] tracking-[-0.03em] text-sense-ink dark:text-slate-50 md:text-[3.05rem]"
          >
            How we calculate Sensory Score
          </h1>
          <p
            class="mt-5 max-w-[820px] text-[1.16rem] font-medium leading-[1.55] tracking-[-0.02em] text-sense-ink/62 dark:text-slate-200 md:text-[1.6rem]"
          >
            We combine different sensory factors into a single score to help you quickly
            understand how a place may feel.
          </p>
        </div>

        <div
          class="mt-7 flex min-h-[100px] md:min-h-[150px] w-full items-center rounded-[22px] bg-white px-4 md:px-8 shadow-[0_8px_24px_rgba(47,73,67,0.06)] dark:bg-[#21363e] overflow-x-auto hide-scrollbar"
        >
          <div class="flex flex-wrap w-full mx-auto md:mx-0 items-center justify-center md:justify-start gap-x-2 gap-y-3 md:gap-x-3 text-left py-4 md:flex-nowrap md:w-max">
            <span
              class="font-display text-[1.25rem] md:text-[1.35rem] font-medium leading-none text-[#104348] dark:text-slate-50 shrink-0 whitespace-nowrap"
            >
              Score =
            </span>

            <template v-for="(factor, index) in scoreFactors" :key="factor.id">
              <div
                class="inline-flex items-center gap-2 md:gap-3 shrink-0"
              >
                <div
                  class="about-tooltip-shell relative inline-flex items-center shrink-0"
                  data-about-tooltip-shell="true"
                  @mouseenter="(e) => showFactorTooltip(factor.id, e.currentTarget as HTMLElement)"
                  @mouseleave="openTooltip = null"
                >
                  <span
                    class="about-chip inline-flex items-center justify-center rounded-[12px] h-[44px] md:h-[49px] px-3 md:px-4 text-[1.05rem] md:text-[1.15rem] font-medium leading-none shrink-0 whitespace-nowrap cursor-default select-none"
                    :class="factor.chipClass"
                    :aria-label="`${factor.label} — hover to learn more`"
                  >
                    {{ factor.label }}
                  </span>

                  <!-- ? button: click for full detail panel -->
                  <button
                    type="button"
                    class="about-mini-badge"
                    :aria-label="`More information about ${factor.label}`"
                    @click.stop="showDetailPanel(factor.id, $event.currentTarget as HTMLElement)"
                  >?</button>
                </div>

                <span
                  class="font-display text-[1.25rem] md:text-[1.35rem] font-medium leading-none text-[#104348] dark:text-slate-50 shrink-0 whitespace-nowrap"
                >
                  {{ factor.weight }}
                </span>

                <span
                  v-if="index < scoreFactors.length - 1"
                  class="font-display text-[1.25rem] md:text-[1.35rem] font-medium leading-none text-[#104348] dark:text-slate-50 shrink-0 whitespace-nowrap"
                  aria-hidden="true"
                >
                  +
                </span>
              </div>
            </template>
          </div>
        </div>

        <!-- Factor tooltips rendered via Teleport to escape overflow-x:auto clipping -->
        <Teleport to="body">
          <Transition name="tooltip-fade-fixed">
            <div
              v-if="openTooltip && openTooltip !== 'statistic'"
              class="about-tooltip-fixed"
              :style="{
                left: factorTooltipStyle.left,
                top: factorTooltipStyle.top,
                '--tooltip-bg': currentFactor?.tooltipBg ?? '#EEEFEA',
                '--tooltip-border': currentFactor?.tooltipBorder ?? '#7AA08C',
                '--tooltip-color': currentFactor?.tooltipColor ?? '#26524B',
              }"
              role="tooltip"
              :aria-label="`${openTooltip} explanation`"
            >
              {{ currentFactorTooltip }}
            </div>
          </Transition>
        </Teleport>

        <!-- Detail panel (large popup on ? click) via Teleport -->
        <Teleport to="body">
          <Transition name="detail-panel-fade">
            <div
              v-if="detailPanelOpen && detailFactor"
              class="about-detail-panel"
              :style="{
                left: detailPanelStyle.left,
                top: detailPanelStyle.top,
                '--tooltip-bg': detailFactor.tooltipBg,
                '--tooltip-border': detailFactor.tooltipBorder,
                '--tooltip-color': detailFactor.tooltipColor,
              }"
              role="dialog"
              :aria-label="`${detailFactor.label} detailed information`"
            >
              <div class="about-detail-panel__icon" aria-hidden="true">?</div>

              <p
                v-for="(para, i) in detailFactor.detailParagraphs"
                :key="i"
                class="about-detail-panel__para"
              >{{ para }}</p>

              <div class="about-detail-panel__refs">
                <a
                  v-for="ref in detailFactor.references"
                  :key="ref.url"
                  :href="ref.url"
                  target="_blank"
                  rel="noopener noreferrer"
                  class="about-detail-panel__ref-link"
                >{{ ref.label }}</a>
              </div>
            </div>
          </Transition>
        </Teleport>

        <p
          class="mt-14 text-center text-[1.05rem] font-medium leading-[1.5] tracking-[-0.02em] text-sense-ink/58 dark:text-slate-300 md:text-[1.55rem]"
        >
          Scores range from 1 (calm) to 4 (busy). This is a guide, not a guarantee.
        </p>

        <div
          class="mt-6 rounded-[14px] bg-[#d5e5d2] px-4 py-4 dark:bg-[#244336] md:px-6"
        >
          <div
            class="flex flex-col items-center justify-center gap-3 text-center md:flex-row md:justify-start md:text-left"
          >
            <InfoCircleIcon class="h-7 w-7 shrink-0 text-[#415954] dark:text-[#b6d2c0]" aria-hidden="true" />
            <p
              class="text-[1rem] font-medium leading-[1.55] tracking-[-0.02em] text-[#415954] dark:text-[#d8e8dd] md:text-[1.35rem]"
            >
              Different people are affected by different factors. You can choose filters by
              your needs.
            </p>
          </div>
        </div>
      </section>

      <section
        class="rounded-[30px] bg-white/60 p-5 shadow-[0_18px_42px_rgba(43,73,73,0.06)] dark:bg-[#162a32] dark:shadow-[0_22px_48px_rgba(0,0,0,0.25)] md:p-8"
      >
        <div class="grid gap-6 lg:grid-cols-[minmax(0,0.92fr)_minmax(0,1.08fr)] items-center">
