const openTooltip = ref<TooltipId | null>(null);

// Fixed-position state for factor tooltips (escape overflow container)
const factorTooltipStyle = ref({ left: '0px', top: '0px' });
const currentFactor = computed(
  () => scoreFactors.find((f) => f.id === openTooltip.value) ?? null,
);
const currentFactorTooltip = computed(() => currentFactor.value?.tooltip ?? '');

function showFactorTooltip(id: TooltipId, el: HTMLElement | null) {
  if (!el) return;
  const rect = el.getBoundingClientRect();
  factorTooltipStyle.value = {
    left: `${rect.left + rect.width / 2}px`,
    top: `${rect.bottom + 10}px`,
  };
  openTooltip.value = id;
}

function toggleTooltip(id: TooltipId) {
  openTooltip.value = openTooltip.value === id ? null : id;
}

// Detail panel state (large popup on ? click)
const detailPanelOpen = ref(false);
const detailPanelFactorId = ref<Exclude<TooltipId, 'statistic'> | null>(null);
const detailPanelStyle = ref({ left: '0px', top: '0px' });
const detailFactor = computed(
  () => scoreFactors.find((f) => f.id === detailPanelFactorId.value) ?? null,
);

function showDetailPanel(id: Exclude<TooltipId, 'statistic'>, el: HTMLElement | null) {
  if (!el) return;
  openTooltip.value = null; // dismiss hover tooltip
  if (detailPanelOpen.value && detailPanelFactorId.value === id) {
    closeDetailPanel();
    return;
  }
  const rect = el.getBoundingClientRect();
  const panelWidth = Math.min(320, window.innerWidth - 32); // 20rem or viewport - padding
  const idealLeft = rect.left + rect.width / 2;
  // Clamp so panel stays within viewport
  const clampedLeft = Math.max(panelWidth / 2 + 12, Math.min(idealLeft, window.innerWidth - panelWidth / 2 - 12));
  detailPanelStyle.value = {
    left: `${clampedLeft}px`,
    top: `${rect.bottom + 14}px`,
  };
  detailPanelFactorId.value = id;
  detailPanelOpen.value = true;
}

function closeDetailPanel() {
  detailPanelOpen.value = false;
  setTimeout(() => { detailPanelFactorId.value = null; }, 300);
}

function handleTooltipMouseDown(event: MouseEvent) {
  const target = event.target;
  if (target instanceof Element && target.closest('[data-about-tooltip-shell="true"]')) {
    return;
  }
  if (target instanceof Element && target.closest('.about-detail-panel')) {
    return; // allow clicks inside the panel (e.g. reference links)
  }
  openTooltip.value = null;
  closeDetailPanel();
}

function handleTooltipEscape(event: KeyboardEvent) {
  if (event.key === 'Escape') {
    openTooltip.value = null;
    closeDetailPanel();
  }
}

function handleScroll() {
  openTooltip.value = null;
  closeDetailPanel();
}

onMounted(() => {
  document.addEventListener('mousedown', handleTooltipMouseDown);
  document.addEventListener('keydown', handleTooltipEscape);
  window.addEventListener('scroll', handleScroll, { passive: true });
});

onBeforeUnmount(() => {
  document.removeEventListener('mousedown', handleTooltipMouseDown);
  document.removeEventListener('keydown', handleTooltipEscape);
  window.removeEventListener('scroll', handleScroll);
});
</script>

